import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay, Pagination, Navigation } from "swiper/modules";
import "swiper/css";
import "swiper/css/pagination";
import "swiper/css/navigation";
import api from "@/utils/api";

export default function HomeActualites() {
  const [actualites, setActualites] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchActualites = async () => {
      try {
        const res = await api.get("/actualites", {
          params: { page: 1, limit: 6, sort: "desc" },
        });

        const data = res.data.data;
        if (Array.isArray(data)) {
          setActualites(data);
        } else {
          console.error("❌ Données inattendues :", res.data);
        }
      } catch (error) {
        console.error("Erreur lors du chargement des actualités :", error);
      }
    };

    fetchActualites();
  }, []);

  if (actualites.length === 0) return null;

  return (
    <div className="max-w-6xl mx-auto px-6 py-12 relative">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-3xl font-bold text-gray-900">Actualités À La Une</h2>
        <button
          onClick={() => navigate("/actualites")}
          className="text-sm text-blue-600 font-semibold hover:underline"
        >
          Tous Découvrir
        </button>
      </div>

      <Swiper
        modules={[Autoplay, Pagination, Navigation]}
        spaceBetween={30}
        slidesPerView={1}
        breakpoints={{ 768: { slidesPerView: 2 } }}
        autoplay={{ delay: 6000, disableOnInteraction: false }}
        pagination={{ clickable: true }}
        navigation={{
          nextEl: ".actualite-swiper-next",
          prevEl: ".actualite-swiper-prev",
        }}
        className="relative"
      >
        {actualites.map((actu) => (
          <SwiperSlide key={actu.id}>
            <div className="flex flex-col md:flex-row bg-white border rounded-lg shadow-lg overflow-hidden h-full min-h-[380px]">
              <div className="md:w-1/2">
              <img
                src={
                  actu.image?.startsWith("http")
                    ? actu.image
                    : `https://cdotchad.com/api/${actu.image?.replace(/^\/?uploads\//, "uploads/")}`
                }
                alt={actu.titre}
                className="w-full h-64 md:h-full object-cover"
                onError={(e) => {
                  e.target.onerror = null;
                  e.target.src = "/images/default-news.jpg";
                }}
              />
              </div>
              <div className="p-5 md:w-1/2 flex flex-col justify-between">
                <div>
                  <p className="text-xs text-gray-400 mb-1">
                    {new Date(actu.date_publication).toLocaleDateString("fr-FR")}
                  </p>
                  <h3 className="text-lg font-bold mb-2 text-gray-800">{actu.titre}</h3>
                  <p className="text-sm text-gray-700 mb-4 line-clamp-4">
                    {actu.resume || actu.contenu?.slice(0, 150)}...
                  </p>
                </div>
                <button
                  onClick={() => navigate(`/actualites/${actu.id}`)}
                  className="text-red-600 font-semibold hover:underline self-start"
                >
                  Consulter Maintenant
                </button>
              </div>
            </div>
          </SwiperSlide>
        ))}
      </Swiper>

      {/* 🔽 Boutons navigation */}
      <div className="actualite-swiper-prev absolute top-1/2 -left-4 transform -translate-y-1/2 z-10 cursor-pointer text-red-600 text-3xl select-none">
        ‹
      </div>
      <div className="actualite-swiper-next absolute top-1/2 -right-4 transform -translate-y-1/2 z-10 cursor-pointer text-red-600 text-3xl select-none">
        ›
      </div>
    </div>
  );
}
