import { useEffect, useState } from "react";
import {
  Briefcase,
  UserPlus,
  FileText,
  FileDown,
} from "lucide-react";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";
import api from "@/utils/api";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { BarChart, PieChart, LineChart } from "@/components/admin/Charts";
import ResetDBButton from "@/components/admin/ResetDBButton";
import ImportDBButton from "@/components/admin/ImportDBButton";
import ActualiteStatsCard from "@/components/admin/ActualiteStatsCard";
import TableActualitesStats from "@/components/admin/TableActualitesStats";

export default function DashboardHome() {
  const [stats, setStats] = useState({
    total_offres: 0,
    total_candidatures: 0,
    total_utilisateurs: 0,
    total_actualites: 0,
  });

  const [graphData, setGraphData] = useState([]);
  const [year, setYear] = useState(new Date().getFullYear());
  const [offreId, setOffreId] = useState("");

  const fetchStats = async () => {
    const res = await api.get("/admin/stats");
    setStats(res.data);
  };

  const fetchGraphData = async () => {
    const res = await api.get("/candidatures/stats", {
      params: { year, offre: offreId },
    });
    setGraphData(res.data);
  };

  useEffect(() => {
    fetchStats();
    fetchGraphData();
  }, [year, offreId]);

  const exportPDF = async () => {
    const input = document.getElementById("dashboard-charts");
    const canvas = await html2canvas(input);
    const imgData = canvas.toDataURL("image/png");
    const pdf = new jsPDF("p", "mm", "a4");
    const width = pdf.internal.pageSize.getWidth();
    const height = (canvas.height * width) / canvas.width;
    pdf.addImage(imgData, "PNG", 0, 10, width, height);
    pdf.save(`dashboard-statistiques-${year}.pdf`);
  };

  return (
    <div className="p-4 space-y-6">
      <h1 className="text-2xl font-bold text-gray-800">Tableau de bord</h1>

      {/* Cartes Statistiques */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4" id="dashboard">
        <StatCard title="Offres" icon={<Briefcase className="text-blue-500" />} value={stats.total_offres} />
        <StatCard title="Candidatures" icon={<FileText className="text-green-500" />} value={stats.total_candidatures} />
        <StatCard title="Utilisateurs" icon={<UserPlus className="text-yellow-500" />} value={stats.total_utilisateurs} />
        <StatCard title="Actualités" icon={<FileText className="text-red-500" />} value={stats.total_actualites} />
      </div>

      {/* Filtres */}
      <div className="flex flex-wrap items-center gap-4">
        <select
          value={year}
          onChange={(e) => setYear(e.target.value)}
          className="border rounded px-3 py-1"
        >
          {[2023, 2024, 2025].map((y) => (
            <option key={y} value={y}>
              {y}
            </option>
          ))}
        </select>

        <input
          type="text"
          value={offreId}
          onChange={(e) => setOffreId(e.target.value)}
          placeholder="ID Offre (facultatif)"
          className="border rounded px-3 py-1"
        />

        <Button onClick={exportPDF} className="bg-red-600 text-white hover:bg-red-700">
          <FileDown className="mr-2" size={16} />
          Exporter PDF
        </Button>
      </div>

      {/* Graphiques */}
      <div id="dashboard-charts" className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <h3 className="text-lg font-semibold mb-2">Candidatures par mois</h3>
          <BarChart data={graphData} />
        </div>
        <div>
          <h3 className="text-lg font-semibold mb-2">Répartition par offre</h3>
          <PieChart data={graphData} />
        </div>
        <div className="md:col-span-2">
          <h3 className="text-lg font-semibold mb-2">Tendance annuelle</h3>
          <LineChart data={graphData} />
        </div>
      </div>

      {/* Actions + Stats actualités */}
      <div className="flex flex-wrap gap-4 mt-6">
        <ImportDBButton />
        <ResetDBButton />
      </div>

      <ActualiteStatsCard />
    </div>
  );
}

function StatCard({ title, icon, value }) {
  return (
    <Card>
      <CardContent className="flex items-center gap-4 py-6">
        {icon}
        <div>
          <p className="text-sm text-gray-500">{title}</p>
          <p className="text-xl font-semibold">{value}</p>
        </div>
      </CardContent>
    </Card>
  );
}
