// 📁 src/utils/api.js
import axios from "axios";
import toast from "react-hot-toast";

const api = axios.create({
  baseURL: import.meta.env.PROD
    ? "https://cdotchad.com/api"
    : "http://localhost:5000/api",
  withCredentials: true,
});

api.interceptors.request.use(
  (config) => {
    const token =
      localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

api.interceptors.response.use(
  (response) => response,
  (error) => {
    const status = error?.response?.status;
    if (status === 401 || status === 403) {
      toast.error("Session expirée. Veuillez vous reconnecter.");
      localStorage.removeItem("adminToken");
      localStorage.removeItem("adminUser");
      sessionStorage.removeItem("adminToken");
      sessionStorage.removeItem("adminUser");
      window.location.href = "/admin/login";
    }
    return Promise.reject(error);
  }
);

// ✅ Fonctions publiques ou de lecture
export const fetchServices = async () => {
  const response = await api.get("/services");
  return response.data;
};

export const fetchOffres = async (params = {}) => {
  const response = await api.get("/offres", { params });
  return response.data;
};

export const fetchActualites = async (params = {}) => {
  const response = await api.get("/actualites", { params });
  return response.data;
};

export const fetchGalerie = async (params = {}) => {
  const response = await api.get("/galerie", { params });
  return response.data;
};

export const fetchCandidatures = async (params = {}) => {
  const response = await api.get("/candidatures", { params });
  return response.data;
};

export const fetchUtilisateurs = async () => {
  const response = await api.get("/utilisateurs");
  return response.data;
};

export const envoyerMessageContact = async (data) => {
  const response = await api.post("/contact", data);
  return response.data;
};

export default api;
