import { useNavigate } from "react-router-dom";
import { LogOut } from "lucide-react";

export default function NavbarAdmin() {
  const navigate = useNavigate();

  const handleLogout = () => {
    localStorage.removeItem("adminToken");
    localStorage.removeItem("adminEmail");
    localStorage.removeItem("adminRole");
    navigate("/admin/login");
  };

  return (
    <nav className="bg-red-700 text-white px-6 py-4 flex justify-between items-center shadow-md">
      <div className="text-lg font-bold">CDO Tchad - Espace Administration</div>

      <button
        onClick={handleLogout}
        className="flex items-center gap-2 bg-white text-red-700 font-semibold px-3 py-1 rounded hover:bg-red-100 transition"
      >
        <LogOut className="w-4 h-4" />
        Déconnexion
      </button>
    </nav>
  );
}
