// src/components/Navbar.jsx
import { useLocation, useNavigate, NavLink } from "react-router-dom";
import { useEffect, useState } from "react";
import { Menu, X, Moon, Sun } from "lucide-react";
import { AnimatePresence, motion } from "framer-motion";
import publicRoutes from "@/routes/public/Index";
import { useTheme } from "@/context/ThemeContext";

export default function Navbar() {
  const navigate = useNavigate();
  const location = useLocation();
  const isHome = location.pathname === "/";
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const { darkMode, toggleTheme } = useTheme(); // 🌙 gestion thème

  const handleNavClick = () => setMobileMenuOpen(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  useEffect(() => {
    console.log("Chemin actuel :", location.pathname);
  }, [location.pathname]);

    const navLinks = publicRoutes
      .filter(route => route.name)
      .map((route, index) => (
        <NavLink
          key={index}
          to={route.path}
          className={({ isActive }) =>
            isActive
              ? "underline text-red-500 font-semibold"
              : "hover:underline transition"
          }
        >
          {route.name}
        </NavLink>
      ));

  const baseStyle =
    "fixed top-0 w-full z-50 px-6 py-3 flex items-center justify-between transition-all duration-300";
  const homeStyle = scrolled
    ? "bg-black/70 backdrop-blur text-white shadow-md"
    : "bg-transparent text-white";
  const otherStyle = "bg-primary text-white shadow";

  return (
    <nav className={`${baseStyle} ${isHome ? homeStyle : otherStyle}`}>
      {/* Logo */}
      <div className="text-xl font-bold">
        <img src="/images/logo-cdotchad.png" alt="Logo" className="h-12 w-auto" />
      </div>

      {/* Desktop nav */}
      <div className="hidden md:flex space-x-4 items-center">
        {navLinks}

        {/* 🌗 Toggle thème */}
        <button
          onClick={toggleTheme}
          className="ml-4 p-2 rounded-full hover:bg-white/20 transition"
          title="Changer le thème"
        >
          {darkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
        </button>
      </div>

      {/* Mobile menu icon */}
      <div className="md:hidden flex items-center">
        <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)}>
          {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
        </button>
      </div>

      {/* Menu mobile */}
      <AnimatePresence>
        {mobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.3 }}
            className={`absolute top-full left-0 w-full flex flex-col p-4 space-y-2 shadow-md ${
              isHome ? "bg-black/90 text-white" : "bg-white text-black dark:bg-gray-900 dark:text-white"
            }`}
          >
            {navLinks}
            {/* 🌘 Thème en mobile */}
            <button
              onClick={toggleTheme}
              className="mt-2 self-start flex items-center gap-2 text-sm"
            >
              {darkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
              {darkMode ? "Mode clair" : "Mode sombre"}
            </button>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
}
