// src/pages/admin/AdminLogin.jsx

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { motion } from "framer-motion";
import { useAuth } from "@/context/AuthContext";
import toast from "react-hot-toast";
import logoCDO from "@/assets/logo-cdotchad.png";
import api from "@/utils/api"; // ✅ API dynamique local/prod

export default function AdminLogin() {
  const [email, setEmail] = useState("");
  const [motdepasse, setMotdepasse] = useState("");
  const [rememberMe, setRememberMe] = useState(true);
  const { login } = useAuth();
  const navigate = useNavigate();

  // 🔁 Redirige si déjà connecté
  useEffect(() => {
    const token =
      localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");
    const user =
      JSON.parse(localStorage.getItem("adminUser")) ||
      JSON.parse(sessionStorage.getItem("adminUser"));
    if (token && user) {
      navigate("/admin/dashboard");
    }
  }, [navigate]);

  // 🔐 Soumission
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await api.post("/admin/login", { email, motdepasse });
      const { token, admin } = res.data;

      localStorage.setItem("adminToken", token); // ✅
      localStorage.setItem("adminRole", admin.role); // ✅

      if (!token || !admin) throw new Error("Réponse invalide du serveur.");
      login(token, admin, rememberMe); // AuthContext login

      toast.success("Connexion réussie !");
      navigate("/admin/dashboard");
    } catch (err) {
      console.error("Erreur de connexion :", err.response?.data || err.message);
      toast.error(
        err.response?.data?.message || "Échec de connexion. Vérifiez vos identifiants."
      );
    }
  };

  return (
    <div
      className="min-h-screen flex items-center justify-center px-4 bg-gray-100 dark:bg-gray-900 transition-colors duration-300"
      style={{
        backgroundImage:
          "linear-gradient(to right, rgba(255,255,255,0.9), rgba(255,255,255,0.9)), url('/images/bg-login.jpg')",
        backgroundSize: "cover",
        backgroundPosition: "center",
      }}
    >
      <motion.div
        initial={{ opacity: 0, scale: 0.9, y: 30 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
        className="w-full max-w-md bg-white dark:bg-gray-800/90 backdrop-blur-md p-8 shadow-2xl rounded-xl border border-gray-200 dark:border-gray-700"
      >
        <div className="flex justify-center mb-6">
          <img src={logoCDO} alt="CDO Tchad Logo" className="h-20 w-auto" />
        </div>

        <h2 className="text-2xl font-bold mb-4 text-center text-red-700 dark:text-red-400">
          Connexion Administrateur
        </h2>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block font-medium text-sm dark:text-white">Email</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full border border-gray-300 dark:border-gray-600 p-2 rounded focus:outline-none focus:ring-2 focus:ring-red-500 dark:bg-gray-900 dark:text-white"
              required
            />
          </div>

          <div>
            <label className="block font-medium text-sm dark:text-white">Mot de passe</label>
            <input
              type="password"
              value={motdepasse}
              onChange={(e) => setMotdepasse(e.target.value)}
              className="w-full border border-gray-300 dark:border-gray-600 p-2 rounded focus:outline-none focus:ring-2 focus:ring-red-500 dark:bg-gray-900 dark:text-white"
              required
            />
          </div>

          <div className="flex items-center text-sm dark:text-white">
            <input
              type="checkbox"
              checked={rememberMe}
              onChange={() => setRememberMe(!rememberMe)}
              id="remember"
              className="mr-2"
            />
            <label htmlFor="remember">Se souvenir de moi</label>
          </div>

          <button
            type="submit"
            className="w-full bg-red-600 text-white py-2 rounded hover:bg-red-700 transition"
          >
            Se connecter
          </button>
        </form>
      </motion.div>
    </div>
  );
}